import React, { useEffect, useRef, useState } from 'react';
import { formContainer, modelFormBankContainer } from './formFieldData';
import { Row, Col, Card, Button } from 'react-bootstrap';
// component
import FormLayout from '../../../utils/formLayout';
import Table from '../../../components/Table';
import {
    dateConversion,
    deleteData,
    emiCalculation,
    findArrObj,
    numberToRupeesWords,
    percentageVal,
    showConfirmationDialog,
    showMessage,
    updateData,
    ValtoPercentage,
} from '../../../utils/AllFunction';
import {
} from '../../../redux/actions';
import { useLocation, useNavigate } from 'react-router-dom';
import { usePageTitle, useRedux } from '../../../hooks';
import ModelViewBox from '../../../components/Atom/ModelViewBox';
import { NotificationContainer } from 'react-notifications';
import { Link } from 'react-router-dom';
import moment from 'moment';
import _ from 'lodash';

function Index() {

    usePageTitle({
        title: 'E-mark',
        breadCrumbItems: [
            {
                path: '/e-mark/home',
                label: 'E-mark',
            },
            {
                path: '/e-mark/home',
                label: 'Register Staff',
                active: true,
            },
        ],
    });

    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0].pagePermission, 'label', "Loan Entry");
    const accessIds = (pageAccessData?.[0]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)

    const { dispatch, appSelector } = useRedux();
    const navigate = useNavigate();
    const location = useLocation();
    const { loanDataEdit, isUpdate, loc } = location.state || false;
    const errorHandle = useRef();

    const {
        errorMessage,
    } = appSelector((state) => ({
    }));

    // useStates
    const [state, setState] = useState({
        genderId: 0,
        staffExperiance: [{
            fromDate: '',
            toDate: '',
            positionName: '',
        }]
    });
    const [errors, setErrors] = useState([]);
    const [formFiledData, setFormFiledData] = useState(formContainer);
    const [optionListState, setOptionListState] = useState({
        genderList: [
            { genderId: 0, genderName: 'Male' },
            { genderId: 1, genderName: 'Female' },
            { genderId: 2, genderName: 'Others' },
        ],
        bloodGroupList: [
            {
                bloodGroupdId: 0,
                bloodGroupName: "A+",
            },
            {
                bloodGroupdId: 1,
                bloodGroupName: "A-",
            },
            {
                bloodGroupdId: 2,
                bloodGroupName: "B+",
            },
            {
                bloodGroupdId: 3,
                bloodGroupName: "B-",
            },
            {
                bloodGroupdId: 4,
                bloodGroupName: "AB+",
            },
            {
                bloodGroupdId: 5,
                bloodGroupName: "AB-",
            },
            {
                bloodGroupdId: 6,
                bloodGroupName: "O+",
            },
            {
                bloodGroupdId: 6,
                bloodGroupName: "O-",
            },
        ]
    });

    const onFormClear = () => {

        setFormFiledData(formContainer);
        setState({
            genderId: 0,
            staffExperiance: [{
                fromDate: '',
                toDate: '',
                positionName: '',
            }]
        });
    };

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    };

    const onFormSubmit = async () => {
        const submitRequest = {
            ...state,
        };

        console.log("submitRequest")
        console.log(submitRequest)
    };

    const handleAdd = () => {
        const updatedTabList = _.cloneDeep(formFiledData);
        const experienceSections = updatedTabList.filter((section, i) => {
            return section.formFields.some(field => field.name === 'positionName' && field.inputType === 'text')
        });
        const newExperienceSection = {
            formFields: [
                {
                    label: 'From Date',
                    name: 'fromDate',
                    inputType: 'date',
                    require: true,
                    classStyle: 'col-2',
                    isArray: "staffExperiance",
                    'onChange': 'handleChangeExperiance',
                    index: experienceSections.length
                },
                {
                    label: 'To Date',
                    name: 'toDate',
                    inputType: 'date',
                    require: true,
                    classStyle: 'col-2',
                    isArray: "staffExperiance",
                    'onChange': 'handleChangeExperiance',
                    index: experienceSections.length
                },
                {
                    label: 'Position Name',
                    name: 'positionName',
                    inputType: 'text',
                    placeholder: 'Enter Position Name',
                    require: true,
                    classStyle: 'col-2',
                    isArray: 'staffExperiance',
                    'onChange': 'handleChangeExperiance',
                    index: experienceSections.length
                },
                {
                    label: 'Add',
                    name: 'addButton',
                    inputType: 'button',
                    onClick: 'handleAdd',
                    classStyle: 'col-2',
                },
            ],
        };
        experienceSections.forEach(section => {
            section.formFields = section.formFields.filter(
                field => !(field.inputType === 'button' && field.name === 'addButton')
            );
        });
        if (experienceSections.length > 0) {
            const lastSection = experienceSections[experienceSections.length - 1];
            const lastSectionIndex = updatedTabList.findIndex(section => section === lastSection);
            updatedTabList.splice(lastSectionIndex + 1, 0, newExperienceSection);
        }
        setFormFiledData(updatedTabList);
        const addNewObj = {
            fromDate: '',
            toDate: '',
            positionName: '',
        }
        setState({
            ...state,
            staffExperiance: [...state.staffExperiance, addNewObj]
        });
    };

    const handleChangeExperiance = (event, formName, form) => {
        const { index } = form;
        setState((prev) => {
            const updateData = [...prev.staffExperiance]
            updateData[index] = {
                ...updateData[index],
                [formName]: event.target.value
            }
            return {
                ...prev,
                staffExperiance: updateData,
                [formName]: event.target.value
            }
        })
    }

    return (
        <React.Fragment>
            <NotificationContainer />
            {isUpdate && (
                <Row>
                    <Col className="d-flex justify-content-end">
                        <div>
                            <Link to={'/loan/request'}>
                                <Button className="mb-2">
                                    Back
                                    <span className="cursor-pointer ms-1">
                                        <i className={'fe-arrow-right'}></i>
                                    </span>
                                </Button>
                            </Link>
                        </div>
                    </Col>
                </Row>
            )}
            <Card>
                <Card.Body>
                    <Row>
                        <Col xs={12}>
                            <FormLayout
                                optionListState={optionListState}
                                dynamicForm={formFiledData}
                                handleSubmit={() =>
                                    showConfirmationDialog(
                                        isUpdate
                                            ? 'Do you want to Update application?'
                                            : 'Do you want to Submit application?',
                                        onFormSubmit,
                                        'Yes',
                                        isUpdate ? 'Update' : 'Create',
                                        isUpdate ? 'Successfully Updated' : 'Successfully Created'
                                    )
                                }
                                state={state}
                                setState={setState}
                                ref={errorHandle}
                                onClickCallBack={{
                                    handleAdd: handleAdd
                                }}
                                onChangeCallBack={{
                                    handleChangeExperiance: handleChangeExperiance
                                }}
                                editData={state}
                                // noOfColumns={6}
                                errors={errors}
                                setErrors={setErrors}
                            />
                        </Col>
                    </Row>
                    <div className="d-flex justify-content-end">
                        <Button onClick={onFormClear} className="mx-2" variant="danger">
                            Reset
                        </Button>
                        <Button onClick={handleValidation} variant="success">
                            {isUpdate ? 'Update' : 'Submit'}
                        </Button>
                    </div>
                </Card.Body>
            </Card>
        </React.Fragment>
    );
}

export default Index;
